//! Pause/restart checks use generated bytes and loopback HTTP only.
use super::*;
use crate::download_verification::{Scope, TestDrive};
use std::sync::{Arc, atomic::{AtomicUsize, Ordering}};

#[path = "download_range_fixture.rs"]
mod fixture;

const SOURCE: &str = "generated-pause-source";

async fn wait_for(mut ready: impl FnMut() -> bool) {
    tokio::time::timeout(Duration::from_secs(15), async {
        while !ready() { tokio::time::sleep(Duration::from_millis(10)).await; }
    }).await.expect("generated Pause fixture timed out");
}

fn controls(path: &Path, paused: bool, drain: bool) {
    std::fs::write(path, serde_json::to_vec(&serde_json::json!({
        "actions": if paused { serde_json::json!({"*":"pause", "generated-cancelled":"cancel"}) } else { serde_json::json!({}) },
        "receive_only_pause": true, "drain": drain,
    })).unwrap()).unwrap();
}

#[test]
fn pause_saves_all_received_ram_and_restart_resumes_in_a_fresh_process() {
    let result = std::process::Command::new(std::env::current_exe().unwrap())
        .env("MYCLOUDDRIVER_DOWNLOAD_RAM_LIMIT_BYTES", (4 << 20).to_string())
        .args(["--exact", "download_transport::parts::pause_tests::pause_drain_child", "--ignored", "--nocapture"])
        .output().unwrap();
    assert!(result.status.success(), "{}{}", String::from_utf8_lossy(&result.stdout), String::from_utf8_lossy(&result.stderr));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[ignore = "isolated Pause controls, shared RAM budget and fresh-process resume"]
async fn pause_drain_child() {
    let directory = tempfile::tempdir().unwrap();
    let control = directory.path().join("controls.json");
    std::env::set_var("MYCLOUDDRIVER_TRANSFER_CONTROL", &control);
    for (id, total) in [("generated-pause-complete", 2 << 20), ("generated-pause-serial", 16 << 20),
        ("generated-pause-ranges", fixture::SIZE), ("generated-pause-legacy", 16 << 20)] {
        controls(&control, false, false);
        wait_for(|| transfer_control::action(id).is_none()).await;
        let drive = TestDrive::new(id);
        let reader = drive.hold_read(1 << 20).await;
        let read_step = reader.chunk(256, id).await.unwrap();
        let remote = fixture::Fixture::new(total).await;
        let part = directory.path().join(format!("{id}.part"));
        let legacy = id == "generated-pause-legacy";
        if legacy {
            let mut old = fixture::bytes(0, 12 << 20, 1);
            old[8 << 20] ^= 0xff;
            std::fs::write(&part, old).unwrap();
        }
        let http = reqwest::Client::builder().no_proxy().build().unwrap();
        let mut progress = DownloadProgressContext::new(false, id, "generated.bin");
        progress.source_file_id = SOURCE;
        let received = progress.transferred_bytes.clone();
        let run_path = part.clone(); let url = remote.url.clone(); let run_http = http.clone();
        let attempt = tokio::spawn(async move {
            Scope::new(id.into(), None).run(super::super::attempt(&run_http, &url, total, &run_path, false, progress, None)).await
        });
        wait_for(|| crate::download_buffer::snapshot().used >= 2 << 20).await;
        controls(&control, true, false);
        wait_for(|| transfer_control::pause_receiving(id)).await;
        assert_eq!(transfer_control::disk_action(id), None);
        assert_eq!(transfer_control::disk_action("generated-cancelled"), Some(transfer_control::Action::Cancel));
        assert!(transfer_control::interruptible(id, std::future::ready(())).await.unwrap_err().is::<transfer_control::Paused>());
        tokio::time::sleep(Duration::from_millis(200)).await;
        assert!(!attempt.is_finished() && crate::download_buffer::snapshot().used >= 2 << 20,
            "Pause must retain accepted RAM while the disk is blocked");
        // This disk check was waiting before Pause. It must still run after
        // the older reader releases its lock, without any new reception.
        let pending_id = format!("{id}-pending-check");
        let pending_drive = drive.sibling(&pending_id);
        let probe = directory.path().join("generated-check.bin");
        std::fs::write(&probe, [0x5a; 1024]).unwrap();
        let pending = tokio::spawn(async move {
            let _drive = pending_drive;
            integrity::Prefix::read(&probe, 0, 1024, &pending_id).await.map_err(DlError::into_inner)
        });
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert!(!pending.is_finished());
        drop(read_step); drop(reader);
        let result = tokio::time::timeout(Duration::from_secs(15), attempt).await.unwrap().unwrap();
        tokio::time::timeout(Duration::from_secs(15), pending).await.unwrap().unwrap().unwrap();
        let accepted = received.load(Ordering::Relaxed);
        if total == 2 << 20 {
            result.map_err(DlError::into_inner).unwrap();
            assert_eq!(accepted, total);
            assert_eq!(std::fs::read(&part).unwrap(), fixture::bytes(0, total as usize, 1),
                "An already received file still completes its final verification while paused");
        } else {
            let error = result.err().expect("An incomplete body must remain resumable").into_inner();
            assert!(error.is::<transfer_control::Paused>(), "{error:#}");
            let durable = if total < download_ranges::MIN_PARALLEL_SIZE {
                ResumeState::load(&part, SOURCE, total).unwrap().unwrap().durable_bytes.unwrap()
            } else { load(&part, SOURCE, total).unwrap().unwrap().ranges.received() };
            assert_eq!(durable, accepted, "Every byte received before Pause must reach the synced checkpoint");
            assert!(durable > 0 && durable < total);
            if legacy {
                assert!(durable < 12 << 20, "Exercise a Pause before the old tail has been compared");
                assert_eq!(std::fs::metadata(&part).unwrap().len(), 12 << 20,
                    "Saving comparison progress must retain the unchecked old tail");
            }
            let stopped_at = received.load(Ordering::Relaxed);
            tokio::time::sleep(Duration::from_millis(200)).await;
            assert_eq!(received.load(Ordering::Relaxed), stopped_at, "Paused reception must stop");
            controls(&control, false, false);
            let resumed = std::process::Command::new(std::env::current_exe().unwrap())
                .env("MYCLOUD_PAUSE_RESTART_PART", &part).env("MYCLOUD_PAUSE_RESTART_URL", &remote.url)
                .env("MYCLOUD_PAUSE_RESTART_SIZE", total.to_string())
                .env("MYCLOUDDRIVER_TRANSFER_CONTROL", &control)
                .args(["--exact", "download_transport::parts::pause_tests::pause_restart_child", "--ignored", "--nocapture"])
                .output().unwrap();
            assert!(resumed.status.success(), "{}{}", String::from_utf8_lossy(&resumed.stdout), String::from_utf8_lossy(&resumed.stderr));
            if legacy {
                assert!(remote.requests.lock().unwrap().iter().any(|r| r.ranged && r.start == durable),
                    "A fresh process must resume after the compared prefix, not replay it from zero");
            }
        }
        wait_for(|| crate::download_buffer::snapshot().used == 0).await;
    }
    // Normal Quit still prioritizes draining writers over checks, and never
    // overrides an explicit Cancel.
    controls(&control, true, true);
    wait_for(transfer_control::draining).await;
    assert_eq!(transfer_control::disk_action("generated-paused"), Some(transfer_control::Action::Pause));
    assert!(transfer_control::drainable("generated-cancelled", std::future::ready(())).await.unwrap_err().is::<transfer_control::Cancelled>());
}

#[tokio::test]
#[ignore = "fresh helper process launched by Pause fixture"]
async fn pause_restart_child() {
    let part = PathBuf::from(std::env::var_os("MYCLOUD_PAUSE_RESTART_PART").unwrap());
    let url = std::env::var("MYCLOUD_PAUSE_RESTART_URL").unwrap();
    let total: u64 = std::env::var("MYCLOUD_PAUSE_RESTART_SIZE").unwrap().parse().unwrap();
    let mut progress = DownloadProgressContext::new(false, "generated-restarted", "generated.bin");
    progress.source_file_id = SOURCE;
    let http = reqwest::Client::builder().no_proxy().build().unwrap();
    Scope::new("generated-restarted".into(), None).run(super::super::attempt(&http, &url, total, &part, false, progress, None))
        .await.map_err(DlError::into_inner).unwrap();
    assert_eq!(std::fs::read(&part).unwrap(), fixture::bytes(0, total as usize, 1));
}

