#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
#[ignore = "isolated paused scheduler and deferred read admission"]
async fn paused_deferred_child() {
    let directory = tempfile::tempdir().unwrap();
    let control = directory.path().join("controls.json");
    std::env::set_var("MYCLOUDDRIVER_TRANSFER_CONTROL", &control);
    controls(&control, false, false);
    let id = "generated-paused-deferred-check";
    let drive = TestDrive::new("generated-admission-owner");
    let _sibling = drive.sibling(id);
    let blocker = Scope::new("generated-admission-owner".into(), None);
    let reservation = std::fs::File::create(directory.path().join("generated-reservation")).unwrap();
    reservation.set_len(2 << 30).unwrap();
    let reservation = tokio::fs::File::from_std(reservation);
    drop(blocker.run(crate::download_verification::acquire_async(&reservation, "generated-admission-owner", 2 << 30)).await.unwrap());
    let path = directory.path().join("generated-check.bin");
    std::fs::write(&path, vec![0x5a; 2 << 20]).unwrap();
    let attempts = Arc::new(AtomicUsize::new(0));
    let run_attempts = attempts.clone();
    let completed = Arc::new(AtomicUsize::new(0)); let settled = completed.clone();
    let task = tokio::spawn(async move {
        transfer_control::schedule(vec![id], 1, move |_| {
            let path = path.clone(); let attempts = run_attempts.clone();
            async move {
                transfer_control::metadata_interruptible(id, std::future::ready(())).await?;
                if transfer_control::action(id) == Some(transfer_control::Action::Pause) {
                    assert!(transfer_control::interruptible(id, std::future::ready(())).await.unwrap_err().is::<transfer_control::Paused>());
                }
                attempts.fetch_add(1, Ordering::Relaxed);
                integrity::Prefix::read(&path, 0, 2 << 20, id).await.map_err(DlError::into_inner)?;
                Ok(())
            }
        }, |id| id.to_string(), move |_, result| { result.unwrap(); settled.fetch_add(1, Ordering::Relaxed); }, |_, _, _| {}).await
    });
    wait_for(|| attempts.load(Ordering::Relaxed) == 1).await;
    tokio::time::sleep(Duration::from_millis(30)).await;
    controls(&control, true, false);
    wait_for(|| transfer_control::pause_receiving(id)).await;
    drop(blocker);
    tokio::time::timeout(Duration::from_secs(5), task).await.unwrap().unwrap().unwrap();
    assert_eq!(attempts.load(Ordering::Relaxed), 2);
    assert_eq!(completed.load(Ordering::Relaxed), 1);
}


