#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[ignore = "isolated prefetch, bounded RAM and Pause/Quit controls"]
async fn resume_prefetch_child() {
    let directory = tempfile::tempdir().unwrap();
    let control = directory.path().join("controls.json");
    std::env::set_var("MYCLOUDDRIVER_TRANSFER_CONTROL", &control);
    for (id, total, sparse, quit) in [
        ("generated-prefetch-serial-pause", 16 << 20, false, false),
        ("generated-prefetch-serial-quit", 16 << 20, false, true),
        ("generated-prefetch-ranges-pause", fixture::SIZE, true, false),
        ("generated-prefetch-ranges-quit", fixture::SIZE, true, true),
        ("generated-prefetch-convert-pause", fixture::SIZE, false, false),
        ("generated-prefetch-convert-quit", fixture::SIZE, false, true),
    ] {
        controls(&control, false, false);
        wait_for(|| transfer_control::action(id).is_none() && !transfer_control::draining()).await;
        let drive = TestDrive::new(id);
        let reader = drive.hold_read(1 << 20).await;
        let read_step = reader.chunk(256, id).await.unwrap();
        let remote = fixture::Fixture::new(total).await;
        let prefix = 2 << 20;
        let part = directory.path().join(format!("{id}.part"));
        let original = fixture::bytes(0, prefix as usize, 1);
        if sparse {
            std::fs::write(data_path(&part), &original).unwrap();
            let state = State::new(total, "\"fixture-1\"".into(), prefix);
            let digests = state.covered_ranges().map(|(_, offset, bytes)| {
                let mut hash = integrity::Prefix::new();
                hash.update(&fixture::bytes(offset, bytes as usize, 1)); hash.digest()
            }).collect();
            // No saved identity: this resume must really read its old bytes.
            save_with_hashes(&part, SOURCE, &state, None, false, None, digests, None).unwrap();
        } else {
            std::fs::write(&part, &original).unwrap();
            let mut hash = integrity::Prefix::new(); hash.update(&original);
            ResumeState { file_id: SOURCE.into(), total, etag: "\"fixture-1\"".into(),
                source_revision: None, require_content_hash: false, source_key: Some(source_key(&remote.url)),
                durable_bytes: Some(prefix), unverified_tail: None, prefix_sha256: Some(hash.digest()) }.save(&part).unwrap();
        }
        let mut progress = DownloadProgressContext::new(false, id, "generated.bin");
        progress.source_file_id = SOURCE;
        let received = progress.transferred_bytes.clone();
        let run_path = part.clone(); let url = remote.url.clone();
        let http = reqwest::Client::builder().no_proxy().build().unwrap();
        let attempt = tokio::spawn(async move {
            Scope::new(id.into(), None).run(super::super::attempt(&http, &url, total, &run_path, false, progress, None)).await
        });
        wait_for(|| crate::download_buffer::snapshot().prefetch_bytes > (4 << 20) * 80 / 100).await;
        let buffer = crate::download_buffer::snapshot();
        assert!(received.load(Ordering::Relaxed) > 0 && buffer.prefetch_tasks == 1);
        assert!(buffer.reserved <= buffer.configured, "Speculation must respect the existing shared RAM cap");
        assert!(crate::download_buffer::prefetching(id));
        assert!(!attempt.is_finished());
        let data = if sparse { data_path(&part) } else { part.clone() };
        assert_eq!(std::fs::read(&data).unwrap(), original, "HTTP must not modify unverified disk coverage");
        let traffic = serde_json::to_value(crate::download_verification::traffic_snapshot()).unwrap();
        assert_eq!(traffic["pending_write_bytes"].as_u64(), Some(0), "Unverified RAM cannot force a write turn ahead of its prerequisite checks");
        controls(&control, true, quit);
        wait_for(|| transfer_control::pause_receiving(id)).await;
        assert_eq!(transfer_control::disk_action(id), None, "Quit must finish the checks needed to safely drain received RAM");
        tokio::time::sleep(Duration::from_millis(120)).await;
        assert!(crate::download_buffer::snapshot().prefetch_bytes > 0);
        drop(read_step); drop(reader);
        let result = tokio::time::timeout(Duration::from_secs(20), attempt).await.unwrap().unwrap();
        let error = result.err().expect("An incomplete prefetched body stays resumable").into_inner();
        assert!(error.is::<transfer_control::Paused>(), "{error:#}");
        let accepted = received.load(Ordering::Relaxed);
        let durable = if total < download_ranges::MIN_PARALLEL_SIZE {
            ResumeState::load(&part, SOURCE, total).unwrap().unwrap().durable_bytes.unwrap()
        } else { load(&part, SOURCE, total).unwrap().unwrap().ranges.received() };
        assert_eq!(durable, prefix + accepted, "All accepted pre-verification RAM must reach a durable checkpoint on Pause/Quit");
        wait_for(|| crate::download_buffer::snapshot().used == 0 && crate::download_buffer::snapshot().prefetch_tasks == 0).await;
        assert!(!crate::download_buffer::prefetching(id));
        controls(&control, false, false);
        let resumed = std::process::Command::new(std::env::current_exe().unwrap())
            .env("MYCLOUD_PAUSE_RESTART_PART", &part).env("MYCLOUD_PAUSE_RESTART_URL", &remote.url)
            .env("MYCLOUD_PAUSE_RESTART_SIZE", total.to_string()).env("MYCLOUDDRIVER_TRANSFER_CONTROL", &control)
            .args(["--exact", "download_transport::parts::pause_tests::pause_restart_child", "--ignored", "--nocapture"])
            .output().unwrap();
        assert!(resumed.status.success(), "{}{}", String::from_utf8_lossy(&resumed.stdout), String::from_utf8_lossy(&resumed.stderr));
    }
}


