#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[ignore = "isolated bounded speculative HTTP and generated corrupt prefixes"]
async fn damaged_prefetch_child() {
    let directory = tempfile::tempdir().unwrap();
    for (id, total, sparse) in [("generated-damaged-serial-prefetch", 16 << 20, false),
        ("generated-damaged-range-prefetch", fixture::SIZE, true)] {
        let drive = TestDrive::new(id);
        let reader = drive.hold_read(1 << 20).await;
        let read_step = reader.chunk(256, id).await.unwrap();
        let remote = fixture::Fixture::new(total).await;
        let prefix = 2 << 20;
        let part = directory.path().join(format!("{id}.part"));
        let original = fixture::bytes(0, prefix as usize, 1);
        if sparse {
            let state = State::new(total, "\"fixture-1\"".into(), prefix);
            let digests = state.covered_ranges().map(|(_, offset, bytes)| {
                let mut hash = integrity::Prefix::new(); hash.update(&fixture::bytes(offset, bytes as usize, 1)); hash.digest()
            }).collect();
            save_with_hashes(&part, SOURCE, &state, None, false, None, digests, None).unwrap();
        } else {
            let mut hash = integrity::Prefix::new(); hash.update(&original);
            ResumeState { file_id: SOURCE.into(), total, etag: "\"fixture-1\"".into(),
                source_revision: None, require_content_hash: false, source_key: Some(source_key(&remote.url)),
                durable_bytes: Some(prefix), unverified_tail: None, prefix_sha256: Some(hash.digest()) }.save(&part).unwrap();
        }
        let data = if sparse { data_path(&part) } else { part.clone() };
        let mut damaged = original; damaged[1000] ^= 0xff; std::fs::write(&data, &damaged).unwrap();
        let before = crate::download_buffer::snapshot().prefetch_discarded_bytes;
        let mut progress = DownloadProgressContext::new(false, id, "generated.bin"); progress.source_file_id = SOURCE;
        let run_path = part.clone(); let url = remote.url.clone();
        let attempt = tokio::spawn(async move {
            let http = reqwest::Client::builder().no_proxy().build().unwrap();
            Scope::new(id.into(), None).run(super::super::attempt(&http, &url, total, &run_path, false, progress, None)).await
        });
        wait_for(|| crate::download_buffer::snapshot().prefetch_bytes >= 2 << 20).await;
        assert_eq!(std::fs::read(&data).unwrap(), damaged);
        drop(read_step); drop(reader);
        tokio::time::timeout(Duration::from_secs(20), attempt).await.unwrap().unwrap().map_err(DlError::into_inner).unwrap();
        assert_eq!(std::fs::read(&part).unwrap(), fixture::bytes(0, total as usize, 1), "Only repaired and verified data may be published");
        wait_for(|| crate::download_buffer::snapshot().used == 0 && crate::download_buffer::snapshot().prefetch_tasks == 0).await;
        assert!(crate::download_buffer::snapshot().prefetch_discarded_bytes > before, "Speculative bytes for invalid coverage must be discarded and accounted for");
    }
}

