#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[ignore = "isolated eight-slot receive-ahead admission with generated data"]
async fn full_coverage_admission_child() {
    let directory = tempfile::tempdir().unwrap();
    let total = 4 << 20;
    let remote = fixture::Fixture::new(total).await;
    let drive = TestDrive::new("generated-admission-keeper");
    let reader = drive.hold_read(1 << 20).await;
    let step = reader.chunk(256, "generated-admission-keeper").await.unwrap();
    let original = fixture::bytes(0, total as usize, 1);
    let mut jobs = Vec::new();
    for index in 0..8 {
        let id = format!("generated-already-received-{index}");
        let run_drive = drive.sibling(&id);
        let part = directory.path().join(format!("{id}.part"));
        std::fs::write(data_path(&part), &original).unwrap();
        let mut state = serde_json::to_value(State::new(total, "\"fixture-1\"".into(), total)).unwrap();
        state["pieces"][0]["complete"] = false.into();
        let state: State = serde_json::from_value(state).unwrap();
        assert_eq!(state.received(), total); assert!(!state.complete());
        let mut hash = integrity::Prefix::new(); hash.update(&original);
        save_with_hashes(&part, SOURCE, &state, None, false, None, vec![hash.digest()], None).unwrap();
        let url = remote.url.clone();
        jobs.push(tokio::spawn(async move {
            let _drive = run_drive;
            let mut progress = DownloadProgressContext::new(false, &id, "generated.bin"); progress.source_file_id = SOURCE;
            let http = reqwest::Client::builder().no_proxy().build().unwrap();
            Scope::new(id.clone(), None).run(super::super::attempt(&http, &url, total, &part, false, progress, None)).await
        }));
    }
    wait_for(|| {
        let snapshot = serde_json::to_value(crate::download_verification::traffic_snapshot()).unwrap();
        snapshot["reading_tasks"].as_u64().unwrap() + snapshot["pending_read_tasks"].as_u64().unwrap() >= 9
    }).await;
    // The ninth file has a meaningful suffix still to receive. Eight files
    // awaiting only an EOF replay must not reserve its early receiving slots.
    let id = "generated-real-suffix";
    let run_drive = drive.sibling(id);
    let part = directory.path().join("generated-real-suffix.part");
    let prefix = 2 << 20;
    std::fs::write(&part, &original[..prefix as usize]).unwrap();
    let mut hash = integrity::Prefix::new(); hash.update(&original[..prefix as usize]);
    ResumeState { file_id: SOURCE.into(), total, etag: "\"fixture-1\"".into(), source_revision: None,
        require_content_hash: false, source_key: Some(source_key(&remote.url)), durable_bytes: Some(prefix),
        unverified_tail: None, prefix_sha256: Some(hash.digest()) }.save(&part).unwrap();
    let url = remote.url.clone();
    let mut progress = DownloadProgressContext::new(false, id, "generated.bin"); progress.source_file_id = SOURCE;
    let received = progress.transferred_bytes.clone();
    jobs.push(tokio::spawn(async move {
        let _drive = run_drive;
        let http = reqwest::Client::builder().no_proxy().build().unwrap();
        Scope::new(id.into(), None).run(super::super::attempt(&http, &url, total, &part, false, progress, None)).await
    }));
    let receiving = tokio::time::timeout(Duration::from_secs(10), async {
        while received.load(Ordering::Relaxed) < 1 << 20 { tokio::time::sleep(Duration::from_millis(10)).await; }
    }).await;
    assert!(receiving.is_ok(), "Already received files occupied {} early slots while a real suffix received only {} bytes",
        crate::download_buffer::snapshot().prefetch_tasks, received.load(Ordering::Relaxed));
    assert_eq!(crate::download_buffer::snapshot().prefetch_tasks, 1, "Only the unfinished payload needs early-receive admission");
    for job in &jobs { job.abort(); }
    for job in jobs { let _ = job.await; }
    drop(step); drop(reader);
    wait_for(|| crate::download_buffer::snapshot().used == 0 && crate::download_buffer::snapshot().prefetch_tasks == 0).await;
}
